// Des: HTML to text lines for car pages, keeping JSON-LD
// Flo: scan bytes once > skip script/style/noscript/svg/comments > closing block tags and br flush a line > decode &#N; &#xH; and common named entities > trim and collapse spaces
// I/O: html bytes + arena (caller) > Page{ title, lines, ldjs }; slices live in the arena; never panics on broken HTML
// ===================================================================
const std = @import("std");
pub const Page = struct { titl: []const u8, lins: []const []const u8, ldjs: []const []const u8 };
const Entz = struct { name: []const u8, cpzz: u21 };
const ENTS = [_]Entz{ .{ .name = "amp", .cpzz = '&' }, .{ .name = "lt", .cpzz = '<' }, .{ .name = "gt", .cpzz = '>' }, .{ .name = "quot", .cpzz = '"' }, .{ .name = "apos", .cpzz = '\'' }, .{ .name = "nbsp", .cpzz = ' ' }, .{ .name = "raquo", .cpzz = 0xBB }, .{ .name = "laquo", .cpzz = 0xAB }, .{ .name = "times", .cpzz = 0xD7 }, .{ .name = "aacute", .cpzz = 0xE1 }, .{ .name = "agrave", .cpzz = 0xE0 }, .{ .name = "acirc", .cpzz = 0xE2 }, .{ .name = "atilde", .cpzz = 0xE3 }, .{ .name = "eacute", .cpzz = 0xE9 }, .{ .name = "egrave", .cpzz = 0xE8 }, .{ .name = "ecirc", .cpzz = 0xEA }, .{ .name = "iacute", .cpzz = 0xED }, .{ .name = "igrave", .cpzz = 0xEC }, .{ .name = "oacute", .cpzz = 0xF3 }, .{ .name = "ograve", .cpzz = 0xF2 }, .{ .name = "ocirc", .cpzz = 0xF4 }, .{ .name = "otilde", .cpzz = 0xF5 }, .{ .name = "uacute", .cpzz = 0xFA }, .{ .name = "ugrave", .cpzz = 0xF9 }, .{ .name = "yacute", .cpzz = 0xFD }, .{ .name = "Aacute", .cpzz = 0xC1 }, .{ .name = "Agrave", .cpzz = 0xC0 }, .{ .name = "Eacute", .cpzz = 0xC9 }, .{ .name = "Oacute", .cpzz = 0xD3 }, .{ .name = "Uacute", .cpzz = 0xDA } };
const SKIP = [_][]const u8{ "script", "style", "noscript", "svg" };
const BLOK = [_][]const u8{ "div", "p", "li", "tr", "h1", "h2", "h3", "h4", "h5", "h6", "span", "label", "td", "th", "dt", "dd", "ul", "ol", "section", "table", "header", "footer", "article", "button", "title" };
fn findCase(hayz: []const u8, nedl: []const u8, from: usize) ?usize { var posi = from; while (posi + nedl.len <= hayz.len) : (posi += 1) { if (std.ascii.eqlIgnoreCase(hayz[posi .. posi + nedl.len], nedl)) return posi; } return null; }
fn inzzLisz(list: []const []const u8, name: []const u8) bool { for (list) |item| { if (std.ascii.eqlIgnoreCase(item, name)) return true; } return false; }
pub fn decoEnti(aren: std.mem.Allocator, text: []const u8) ![]const u8 { if (std.mem.indexOfScalar(u8, text, '&') == null) return text; var outp: std.ArrayList(u8) = .empty; var posi: usize = 0; while (posi < text.len) { if (text[posi] != '&') { try outp.append(aren, text[posi]); posi += 1; continue; } const semi = std.mem.indexOfScalarPos(u8, text, posi, ';') orelse { try outp.append(aren, '&'); posi += 1; continue; }; if (semi - posi > 10) { try outp.append(aren, '&'); posi += 1; continue; } const name = text[posi + 1 .. semi]; var cpzz: ?u21 = null; if (name.len > 1 and name[0] == '#') { const hexz = name[1] == 'x' or name[1] == 'X'; const valu = std.fmt.parseInt(u32, if (hexz) name[2..] else name[1..], if (hexz) 16 else 10) catch 0; if (valu > 0 and valu < 0x110000) cpzz = @intCast(valu); } else { for (ENTS) |entz| { if (std.mem.eql(u8, entz.name, name)) cpzz = entz.cpzz; } } if (cpzz) |code| { var buff: [4]u8 = undefined; const lenz = std.unicode.utf8Encode(code, &buff) catch { try outp.append(aren, '&'); posi += 1; continue; }; try outp.appendSlice(aren, buff[0..lenz]); posi = semi + 1; } else { try outp.append(aren, '&'); posi += 1; } } return outp.toOwnedSlice(aren); }
fn flusLinz(aren: std.mem.Allocator, curr: *std.ArrayList(u8), lins: *std.ArrayList([]const u8)) !void { defer curr.clearRetainingCapacity(); if (curr.items.len == 0) return; const deco = try decoEnti(aren, curr.items); var outp: std.ArrayList(u8) = .empty; var spac = true; var pdxz: usize = 0; while (pdxz < deco.len) { const byte = deco[pdxz]; var skip: usize = 1; var blnk = byte == ' ' or byte == '\t' or byte == '\r' or byte == '\n'; if (byte == 0xC2 and pdxz + 1 < deco.len and deco[pdxz + 1] == 0xA0) { blnk = true; skip = 2; } if (byte == 0xE2 and pdxz + 2 < deco.len and deco[pdxz + 1] == 0x80 and (deco[pdxz + 2] == 0xAF or deco[pdxz + 2] == 0x89 or deco[pdxz + 2] == 0x80)) { blnk = true; skip = 3; } if (blnk) { if (!spac) try outp.append(aren, ' '); spac = true; } else { try outp.append(aren, byte); spac = false; } pdxz += skip; } while (outp.items.len > 0 and outp.items[outp.items.len - 1] == ' ') _ = outp.pop(); if (outp.items.len == 0) return; try lins.append(aren, try outp.toOwnedSlice(aren)); }
pub fn pageSpli(aren: std.mem.Allocator, html: []const u8) !Page { var lins: std.ArrayList([]const u8) = .empty; var ldjs: std.ArrayList([]const u8) = .empty; var curr: std.ArrayList(u8) = .empty; var titl: []const u8 = ""; var posi: usize = 0; while (posi < html.len) { const byte = html[posi]; if (byte != '<') { try curr.append(aren, byte); posi += 1; continue; } if (std.mem.startsWith(u8, html[posi..], "<!--")) { const endz = std.mem.indexOfPos(u8, html, posi + 4, "-->") orelse html.len; posi = @min(endz + 3, html.len); continue; } const nexz = if (posi + 1 < html.len) html[posi + 1] else 0; if (!(std.ascii.isAlphabetic(nexz) or nexz == '/')) { try curr.append(aren, '<'); posi += 1; continue; } var endz = posi + 1; var quot: u8 = 0; while (endz < html.len) : (endz += 1) { const chrz = html[endz]; if (quot != 0) { if (chrz == quot) quot = 0; } else if (chrz == '"' or chrz == '\'') quot = chrz else if (chrz == '>') break; } if (endz >= html.len) break; const clos = html[posi + 1] == '/'; var nbeg = posi + 1; if (clos) nbeg += 1; var nend = nbeg; while (nend < endz and (std.ascii.isAlphanumeric(html[nend]))) nend += 1; const name = html[nbeg..nend]; const tagz = html[posi .. endz + 1]; posi = endz + 1; if (!clos and inzzLisz(&SKIP, name) and !std.mem.endsWith(u8, tagz, "/>")) { const clzz = try std.fmt.allocPrint(aren, "</{s}", .{name}); const bodz = posi; const stop = findCase(html, clzz, posi) orelse html.len; if (std.ascii.eqlIgnoreCase(name, "script") and findCase(tagz, "ld+json", 0) != null) try ldjs.append(aren, html[bodz..stop]); const gtzz = std.mem.indexOfScalarPos(u8, html, stop, '>') orelse html.len; posi = @min(gtzz + 1, html.len); continue; } if (!clos and std.ascii.eqlIgnoreCase(name, "title") and titl.len == 0) { const stop = findCase(html, "</title", posi) orelse html.len; titl = std.mem.trim(u8, try decoEnti(aren, html[posi..stop]), " \t\r\n"); posi = stop; continue; } if (std.ascii.eqlIgnoreCase(name, "br") or (clos and inzzLisz(&BLOK, name))) { try flusLinz(aren, &curr, &lins); } else { try curr.append(aren, ' '); } } try flusLinz(aren, &curr, &lins); return .{ .titl = titl, .lins = try lins.toOwnedSlice(aren), .ldjs = try ldjs.toOwnedSlice(aren) }; }
